import{_ as t,o as r,c as a,ag as s}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Entrainement IA","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/ai-training.md","filePath":"fr/guide/ai-training.md"}'),i={name:"fr/guide/ai-training.md"};function n(o,e,l,u,d,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="entrainement-ia" tabindex="-1">Entrainement IA <a class="header-anchor" href="#entrainement-ia" aria-label="Permalink to &quot;Entrainement IA&quot;">​</a></h1><p>La page Entrainement IA vous permet de collecter, organiser et exporter des paires de donnees d&#39;entrainement pour le fine-tuning de modeles de langage.</p><p><strong>Element de la barre laterale :</strong> Entrainement IA <strong>Route :</strong> <code>/training</code></p><h2 id="que-sont-les-paires-d-entrainement" tabindex="-1">Que sont les paires d&#39;entrainement ? <a class="header-anchor" href="#que-sont-les-paires-d-entrainement" aria-label="Permalink to &quot;Que sont les paires d&#39;entrainement ?&quot;">​</a></h2><p>Une paire d&#39;entrainement se compose d&#39;un <strong>prompt utilisateur</strong> et d&#39;une <strong>reponse du modele</strong>. En collectant des paires de haute qualite, vous constituez un jeu de donnees qui peut etre utilise pour affiner un modele afin qu&#39;il se comporte comme vous le souhaitez.</p><h2 id="comment-les-paires-sont-collectees" tabindex="-1">Comment les paires sont collectees <a class="header-anchor" href="#comment-les-paires-sont-collectees" aria-label="Permalink to &quot;Comment les paires sont collectees&quot;">​</a></h2><p>Les paires d&#39;entrainement sont automatiquement capturees a partir de vos interactions avec la fonctionnalite <strong>Canvas AI</strong> de l&#39;Atelier d&#39;Outils. Lorsque l&#39;IA genere du code d&#39;outil, propose des ameliorations ou fournit des analyses, chaque interaction devient une paire d&#39;entrainement stockee dans IndexedDB.</p><h2 id="organiser-les-donnees" tabindex="-1">Organiser les donnees <a class="header-anchor" href="#organiser-les-donnees" aria-label="Permalink to &quot;Organiser les donnees&quot;">​</a></h2><p>L&#39;interface principale affiche un tableau de toutes les paires d&#39;entrainement collectees. Pour chaque paire, vous pouvez :</p><h3 id="accepter-ou-rejeter" tabindex="-1">Accepter ou rejeter <a class="header-anchor" href="#accepter-ou-rejeter" aria-label="Permalink to &quot;Accepter ou rejeter&quot;">​</a></h3><ul><li><strong>Accepter</strong> -- Marquer la paire comme donnee d&#39;entrainement de haute qualite</li><li><strong>Rejeter</strong> -- La marquer comme inadaptee (mauvaise sortie, hallucination, etc.)</li></ul><h3 id="modifier-les-reponses" tabindex="-1">Modifier les reponses <a class="header-anchor" href="#modifier-les-reponses" aria-label="Permalink to &quot;Modifier les reponses&quot;">​</a></h3><p>Cliquez sur n&#39;importe quelle reponse pour la modifier. C&#39;est utile lorsque la sortie du modele etait presque correcte mais necessite une correction -- vous obtenez la bonne reponse sans repartir de zero.</p><h3 id="etiquetage" tabindex="-1">Etiquetage <a class="header-anchor" href="#etiquetage" aria-label="Permalink to &quot;Etiquetage&quot;">​</a></h3><p>Ajoutez des etiquettes pour organiser les paires par sujet, niveau de qualite ou toute categorie personnalisee. Les etiquettes vous aident a filtrer et exporter des sous-ensembles specifiques.</p><h3 id="operations-en-masse" tabindex="-1">Operations en masse <a class="header-anchor" href="#operations-en-masse" aria-label="Permalink to &quot;Operations en masse&quot;">​</a></h3><p>Selectionnez plusieurs paires pour :</p><ul><li><strong>Accepter/rejeter en masse</strong> -- Definir le statut de nombreuses paires d&#39;un coup</li><li><strong>Ajouter des etiquettes en masse</strong> -- Appliquer une etiquette a toutes les paires selectionnees</li><li><strong>Supprimer</strong> -- Retirer les paires non desirees</li></ul><h2 id="filtrage" tabindex="-1">Filtrage <a class="header-anchor" href="#filtrage" aria-label="Permalink to &quot;Filtrage&quot;">​</a></h2><p>Filtrez la liste des paires d&#39;entrainement par :</p><ul><li><strong>Statut</strong> -- Acceptees, rejetees ou non examinees</li><li><strong>Etiquettes</strong> -- Afficher uniquement les paires avec des etiquettes specifiques</li><li><strong>Recherche</strong> -- Recherche en texte libre dans les prompts et les reponses</li></ul><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Selectionnez les paires a exporter (ou utilisez les filtres pour affiner), puis cliquez sur <strong>Exporter</strong>. Le jeu de donnees exporte peut etre utilise avec des outils et frameworks de fine-tuning.</p><h2 id="statistiques" tabindex="-1">Statistiques <a class="header-anchor" href="#statistiques" aria-label="Permalink to &quot;Statistiques&quot;">​</a></h2><p>L&#39;en-tete de la page affiche des statistiques agregees :</p><ul><li>Nombre total de paires collectees</li><li>Nombre d&#39;acceptees vs. rejetees</li><li>Repartition des etiquettes</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>La qualite prime sur la quantite</strong> -- Un petit jeu de donnees soigneusement organise produit de meilleurs resultats de fine-tuning qu&#39;un grand jeu de donnees bruite.</li><li><strong>Modifiez plutot que de jeter</strong> -- Si une reponse est correcte a 80 %, la modifier est plus efficace que de regenerer a partir de zero.</li><li><strong>Utilisez les etiquettes strategiquement</strong> -- Etiquetez par capacite (par ex., &quot;code-gen&quot;, &quot;api-tools&quot;, &quot;explication&quot;) pour creer des sous-ensembles d&#39;entrainement cibles.</li></ul>',28)])])}const q=t(i,[["render",n]]);export{m as __pageData,q as default};
